// 1. Gemini ka text output uthao
const rawText = $input.first().json.content.parts[0].text;

// 2. Markdown (```json aur ```) ko hata kar text ko saaf karo
const cleanString = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. Uss saaf text ko asli JSON array mein convert (parse) karo
const parsedArray = JSON.parse(cleanString);

// 4. Array ke har ek item ko n8n ke alag-alag task (item) mein badal do
return parsedArray.map(item => {
  return {
    json: item
  };
});

let score = 0;
if ($input.first().json.case_number && $input.first().json.amount && $input.first().json.check_date) { score += 0.5; }
if (/^[0-9A-Z-]+$/.test($input.first().json.case_number)) { score += 0.2; }
if (typeof $input.first().json.amount === 'number' && $input.first().json.amount > 0) { score += 0.2; }

const items = $input.all().map(item => ({
  json: {
    ...item.json,
    score: score
  }
}));
return items;

// Access previous nodes data
const freshReceipts = $("Calculate Score & Format").all();
const dbDuplicates = $("Check Duplicates").all().filter(i => i.json.id);
const allTenants = $("Get All Tenants").all();

return freshReceipts.map(item => {
  const receipt = item.json;

  // 1. Find Tenant Match (Case Number) 
  const tenant = allTenants.find(t => t.json.case_number === receipt.case_number);

  // 2. Find Duplicate Match (Case# + Check# + Amount)
  const duplicate = dbDuplicates.find(d =>
    d.json.extracted_case_number === receipt.case_number &&
    d.json.extracted_check_number === receipt.check_number &&
    d.json.extracted_amount === receipt.amount
  );

  // 3. Define Final Status Logic
  let status = 'needs_review';

  if (duplicate) {
    status = 'duplicate_suspected'; // High priority
  } else if (receipt.score > 0.75 && tenant) {
    status = 'processing'; // Auto-process if clear
  }

  // Returning keys that match Supabase columns exactly
  return {
    json: {
      case_number: receipt.case_number,
      check_number: receipt.check_number,
      extracted_amount: receipt.amount,
      extracted_check_date: receipt.check_date,
      extracted_rent_from: receipt.rent_from,
      extracted_rent_to: receipt.rent_to,
      page_number: receipt.page_number,
      matched_tenant_id: tenant ? tenant.json.id : null,
      duplicate_suspected: !!duplicate,
      duplicate_reference_id: duplicate ? duplicate.json.id : null,
      status: status,
      ocr_confidence: receipt.score
    }
  };
});

