// Dono nodes ka total item count nikalna
const blankCount = $("Insert is_blank row in transactions table").all().length;
const insertCount = $("Insert Row Into Transactions Table").all().length;

// Email node ke liye ek single item return karna
return [
  {
    json: {
      blank_pages: blankCount,
      processed_pages: insertCount,
      total_pages: blankCount + insertCount
    }
  }
];

// ─── GET DATA ────────────────────────────────────────────────────────────────
const tenant     = $('Fetch Tenant Data').first().json;
const ledgerRows = $('Fetch Monthly Ledger').all().map(i => i.json);  // view_rent_ledger
const checkRows  = $('Fetch Check Details').all().map(i => i.json);   // transactions

const tenantName = tenant.full_legal_name || tenant.name || '—';
const caseNumber = tenant.case_number || '—';
const address    = tenant.address || '—';
const today      = new Date().toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});

// ─── STEP 1: INDEX CHECKS BY MONTH ───────────────────────────────────────────
// Build a map: "2021-12" → [check1, check2, check3...]
const checksByMonth = {};

checkRows.forEach(row => {
  const dateStr = row.extracted_check_date || row.date;
  if (!dateStr) return;
  const d   = new Date(dateStr);
  const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  if (!checksByMonth[key]) checksByMonth[key] = [];
  checksByMonth[key].push(row);
});

// ─── STEP 2: FIND MAX HRA COLUMNS NEEDED ─────────────────────────────────────
let maxHRA = 4; // Sonu's template shows 4 — minimum 4
Object.values(checksByMonth).forEach(arr => {
  if (arr.length > maxHRA) maxHRA = arr.length;
});

// ─── STEP 3: BUILD FLAT ROWS (for Excel/CSV) ─────────────────────────────────
const flatRows  = [];
const monthNames = ['Jan','Feb','Mar','Apr','May','Jun',
                    'Jul','Aug','Sep','Oct','Nov','Dec'];

// Track year for grouping (show year only when it changes)
let lastYear = null;

ledgerRows.forEach(ledgerRow => {
  // Parse the month date from view_rent_ledger
  const monthDate = new Date(ledgerRow.month);
  const year      = monthDate.getFullYear();
  const monthIdx  = monthDate.getMonth();
  const monthKey  = `${year}-${String(monthIdx+1).padStart(2,'0')}`;
  const monthShort= monthNames[monthIdx];

  // Get checks for this month
  const monthChecks = checksByMonth[monthKey] || [];
  const isCash      = (row) => row.type === 'cash' || row.payment_type === 'cash';

  const hraChecks  = monthChecks.filter(r => !isCash(r));
  const cashChecks = monthChecks.filter(r => isCash(r));
  const cashTotal  = cashChecks.reduce((s, r) => s + (parseFloat(r.extracted_amount)||0), 0);

  // HRA amounts
  const hraObj = {};
  for (let i = 1; i <= maxHRA; i++) {
    const chk = hraChecks[i-1];
    hraObj[`HRA ${i}`] = chk ? parseFloat(chk.extracted_amount)||'' : '';
  }

  // Balance from view_rent_ledger (already calculated with carryover)
  const balance    = parseFloat(ledgerRow.pending_balance) || 0;
  const monthlyDue = parseFloat(ledgerRow.due_amount) || 0;

  flatRows.push({
    'Year':    year,
    'Month':   monthShort,
    'Monthly': monthlyDue || '',
    ...hraObj,
    'Cash':    cashTotal > 0 ? cashTotal : '',
    'Balance': balance !== 0 ? balance : 0,
    'Comments': ''
  });
});

// ─── STEP 4: BUILD HTML ───────────────────────────────────────────────────────
const thSt = 'padding:7px 10px; border:1px solid #999; background:#1a3c5e; color:white; text-align:center; font-size:11px;';
const tdSt = 'padding:6px 10px; border:1px solid #ddd; text-align:right; font-size:11px;';
const tdL  = 'padding:6px 10px; border:1px solid #ddd; text-align:left; font-size:11px;';
const yrSt = 'padding:6px 10px; border:1px solid #ddd; text-align:center; font-weight:bold; color:#1a3c5e; font-size:12px;';

// Count rows per year for rowspan
const yearCount = {};
flatRows.forEach(r => { yearCount[r.Year] = (yearCount[r.Year]||0) + 1; });
const yearDone  = {};

let hraHeaders = '';
for (let i = 1; i <= maxHRA; i++) {
  hraHeaders += `<th style="${thSt}">HRA ${i}</th>`;
}

let tbodyHTML    = '';
let grandDue     = 0;
let grandPaid    = 0;
let grandBalance = 0;

flatRows.forEach(row => {
  // Year cell with rowspan
  let yearCell = '';
  if (!yearDone[row.Year]) {
    yearCell = `<td rowspan="${yearCount[row.Year]}" style="${yrSt}">${row.Year}</td>`;
    yearDone[row.Year] = true;
  }

  // HRA cells
  let hraCells = '';
  for (let i = 1; i <= maxHRA; i++) {
    const val = row[`HRA ${i}`];
    hraCells += `<td style="${tdSt}">${val !== '' && val !== undefined ? '$'+Number(val).toLocaleString('en-US',{minimumFractionDigits:2}) : ''}</td>`;
  }

  // Cash cell
  const cashStr = row.Cash ? '$'+Number(row.Cash).toLocaleString('en-US',{minimumFractionDigits:2}) : '';

  // Balance color: positive = owes (red), negative = credit (green), zero = black
  const bal       = Number(row.Balance);
  const balColor  = bal > 0 ? '#c0392b' : bal < 0 ? '#27ae60' : '#222';
  const balStr    = bal !== 0
    ? `<span style="color:${balColor}; font-weight:bold;">${bal > 0 ? '-$'+bal.toLocaleString('en-US',{minimumFractionDigits:2}) : '+$'+Math.abs(bal).toLocaleString('en-US',{minimumFractionDigits:2})}</span>`
    : '$0.00';

  const monthlyStr = row.Monthly ? '$'+Number(row.Monthly).toLocaleString('en-US',{minimumFractionDigits:2}) : '';

  grandDue     += Number(row.Monthly) || 0;
  grandBalance  = bal; // last row balance IS the running total

  tbodyHTML += `
    <tr>
      ${yearCell}
      <td style="${tdL}">${row.Month}</td>
      <td style="${tdSt}">${monthlyStr}</td>
      ${hraCells}
      <td style="${tdSt}">${cashStr}</td>
      <td style="${tdSt}">${balStr}</td>
      <td style="${tdSt}"></td>
    </tr>`;
});

// Grand total row
let hraEmptyCells = '';
for (let i = 1; i <= maxHRA; i++) hraEmptyCells += '<td></td>';

const grandBalColor = grandBalance > 0 ? '#c0392b' : '#27ae60';
tbodyHTML += `
  <tr style="background:#f0f4f8; font-weight:bold; border-top:2px solid #1a3c5e;">
    <td colspan="2" style="padding:8px 10px; border:1px solid #ccc;">TOTAL</td>
    <td style="${tdSt}">$${grandDue.toLocaleString('en-US',{minimumFractionDigits:2})}</td>
    ${hraEmptyCells}
    <td></td>
    <td style="${tdSt}; color:${grandBalColor};">
      ${grandBalance > 0 ? '-$'+grandBalance.toLocaleString('en-US',{minimumFractionDigits:2}) : '+$'+Math.abs(grandBalance).toLocaleString('en-US',{minimumFractionDigits:2})}
    </td>
    <td></td>
  </tr>`;

const html = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; font-size:12px; margin:30px; color:#222; }
  h1   { font-size:16px; margin-bottom:4px; }
  .meta { border-bottom:2px solid #1a3c5e; padding-bottom:10px; margin-bottom:16px; }
  .meta p { margin:3px 0; }
  table { width:100%; border-collapse:collapse; }
  .disc { margin-top:20px; padding:8px; background:#fff8e1; border:1px solid #f0c040; font-size:10px; color:#555; }
</style>
</head>
<body>
<h1>Rental Payment Ledger</h1>
<div class="meta">
  <p><strong>Tenant:</strong> ${tenantName}</p>
  <p><strong>Case Number:</strong> ${caseNumber}</p>
  <p><strong>Address:</strong> ${address}</p>
  <p><strong>Report Date:</strong> ${today}</p>
</div>
<table>
  <thead>
    <tr>
      <th style="${thSt}">Year</th>
      <th style="${thSt}">Month</th>
      <th style="${thSt}">Monthly</th>
      ${hraHeaders}
      <th style="${thSt}">Cash</th>
      <th style="${thSt}">Balance</th>
      <th style="${thSt}">Comments</th>
    </tr>
  </thead>
  <tbody>${tbodyHTML}</tbody>
</table>
<div class="disc">
  This document is generated by LandlordOS. Verify all figures against original documentation before use in legal proceedings.
</div>
</body></html>`;

const filename = `ledger_${tenantName.replace(/\s+/g,'_')}_${new Date().toISOString().split('T')[0]}`;

return [{ json: { html, flatRows, filename, tenantName, caseNumber } }];

